<?php
namespace STS\Mobility\Commute;
use Carbon\CarbonImmutable;
use Illuminate\Database\QueryException;
use Illuminate\Support\Facades\DB;
use STS\Models\{User,Trip,Passenger};
use STS\Mobility\Segments\SegmentException;
use STS\Mobility\Trust\CohortPolicy;
final class CommuteService {
 public static function demoEnabled():bool{return app()->environment('testing')&&filter_var(getenv('MOBILITY_PILOT_UI_ENABLED'),FILTER_VALIDATE_BOOLEAN);}
 public static function demoActor(int$id):bool{return self::demoEnabled()&&DB::table('mobility_commute_demo_actors')->where('user_id',$id)->exists();}
 public function requireDemo(User$u):void{if(!self::demoActor($u->id)||!CohortPolicy::approved($u->id))throw new SegmentException('DEMO_SESSION_REQUIRED',403);}
 private function actor(string$key,string$name):User {
  $row=DB::table('mobility_commute_demo_actors')->where('fixture_key',$key)->first();if($row)return User::findOrFail($row->user_id);
  return DB::transaction(function()use($key,$name){$email='commute-'.$key.'@example.invalid';$u=User::where('email',$email)->lockForUpdate()->first();if(!$u)$u=User::factory()->create(['email'=>$email,'name'=>$name,'active'=>true,'banned'=>false]);
   DB::table('mobility_commute_demo_actors')->insertOrIgnore(['user_id'=>$u->id,'fixture_key'=>$key,'created_at'=>now(),'updated_at'=>now()]);
   DB::table('mobility_memberships')->insertOrIgnore(['user_id'=>$u->id,'college_code'=>CohortPolicy::college(),'affiliation'=>'student','status'=>'approved','version'=>1,'created_at'=>now(),'updated_at'=>now()]);return$u;});
 }
 public function demoSession(string$role,?string$scenario=null):array {
  if(!self::demoEnabled())abort(404);$u=$this->actor($scenario==='campus-route'?($role==='driver'?'campus-driver-car':'campus-rider'):($role==='driver'?'driver-car':'rider'),$scenario==='campus-route'?($role==='driver'?'Yeshwanthpur Driver':'Laggere Rider'):'Demo '.ucfirst($role));
  return ['token'=>auth('api')->fromUser($u),'user'=>['id'=>$u->id,'name'=>$u->name,'email'=>$u->email],'profile'=>$this->profile($u),'driver_approved'=>$this->driverApproved($u),'demo'=>true,'scenario'=>$scenario];
 }
 public function profile(User$u):?array{$p=DB::table('mobility_commute_profiles')->where('user_id',$u->id)->value('preferences');return$p?json_decode($p,true):null;}
 public function driverApproved(User$u):bool {
  if(!CohortPolicy::activeUser($u)||!CohortPolicy::approved($u->id))return false;
  return (self::demoActor($u->id)&&DB::table('mobility_commute_demo_actors')->where('user_id',$u->id)->whereIn('fixture_key',['driver-car','campus-driver-car'])->exists())||CohortPolicy::hostApproved($u->id);
 }
 public function me(User$u):array{return['user'=>['id'=>$u->id,'name'=>$u->name,'email'=>$u->email],'profile'=>$this->profile($u),'demo'=>self::demoActor($u->id),'driver_approved'=>$this->driverApproved($u)];}
 public function saveProfile(User$u,array$v):array{
  if(isset($v['name'])){$u->name=$v['name'];$u->save();}unset($v['name']);$v['onboarding_complete']=true;
  DB::table('mobility_commute_profiles')->updateOrInsert(['user_id'=>$u->id],['preferences'=>json_encode($v,JSON_THROW_ON_ERROR),'created_at'=>now(),'updated_at'=>now()]);return$this->me($u);
 }
 public function rides(User$rider,string$direction,string$date,string$vehicle,string$pickupChoice='both',string$startTime='',string$endTime=''):array {
  return app(CommuteMatchingService::class)->rides($rider,$direction,$date,$vehicle,$pickupChoice,$startTime,$endTime);
 }
 private function quoteToken(object$m,User$u):string{return hash_hmac('sha256',$m->trip_id.':'.$u->id.':'.$m->fare_minor.':'.$m->fixture_key,(string)config('app.key'));}
 public function request(User$u,int$tripId,string$quote):array {
  $this->requireDemo($u);return DB::transaction(function()use($u,$tripId,$quote){$trip=Trip::whereKey($tripId)->lock('for update nowait')->firstOrFail();$meta=DB::table('mobility_commute_demo_trips')->where('trip_id',$tripId)->first();
   if($meta&&$meta->is_publication)return app(CommuteMatchingService::class)->request($u,$trip,$quote);
   if(!$meta||(int)$meta->audience_id!==$u->id||!hash_equals($this->quoteToken($meta,$u),$quote))throw new SegmentException('COMMUTE_QUOTE_CHANGED',409);
   $profile=$this->profile($u);$matches=false;
   if($profile){$date=CarbonImmutable::parse($trip->trip_date,'Asia/Kolkata')->format('Y-m-d');foreach(['outbound','return']as$direction){$from=$profile[$direction==='outbound'?'home':'campus'];$to=$profile[$direction==='outbound'?'campus':'home'];$time=$profile[$direction==='outbound'?'outbound_time':'return_time'];$current=hash('sha256',json_encode([$u->id,$meta->vehicle_type,$date,$direction,$time,$from,$to]));if(hash_equals($meta->fixture_key,$current))$matches=true;}}
   if(!$matches)throw new SegmentException('COMMUTE_QUOTE_CHANGED',409);
   if($trip->user_id==$u->id)throw new SegmentException('RIDER_CANNOT_BE_DRIVER',403);$this->planned($trip);
   $old=Passenger::where('trip_id',$tripId)->where('user_id',$u->id)->whereIn('request_state',[0,1])->first();
   if(!$old)$old=Passenger::create(['trip_id'=>$tripId,'user_id'=>$u->id,'request_state'=>0,'passenger_type'=>Passenger::TYPE_PASAJERO]);return['data'=>$this->bookingDto($old,$u)];});
 }
 private function planned(Trip$t):void{if(DB::table('mobility_trip_lifecycles')->where('trip_id',$t->id)->value('state')!=='planned'||CarbonImmutable::parse($t->trip_date,'Asia/Kolkata')->lte(now('Asia/Kolkata')))throw new SegmentException('COMMUTE_TRIP_CLOSED',409);}
 public function bookings(User$u):array{
  $this->requireDemo($u);$rows=Passenger::whereExists(fn($q)=>$q->selectRaw('1')->from('mobility_commute_demo_trips')->whereColumn('mobility_commute_demo_trips.trip_id','trip_passengers.trip_id'))->where(function($q)use($u){$q->where('user_id',$u->id)->orWhereExists(fn($t)=>$t->selectRaw('1')->from('trips')->whereColumn('trips.id','trip_passengers.trip_id')->where('trips.user_id',$u->id));})->orderByDesc('id')->limit(50)->get();return['data'=>$rows->map(fn($b)=>$this->bookingDto($b,$u))->all()];
 }
 public function bookingDto(Passenger$b,User$u):array{
  $trip=Trip::findOrFail($b->trip_id);if((int)$b->user_id!==$u->id&&(int)$trip->user_id!==$u->id)throw new SegmentException('TRIP_FORBIDDEN',403);
  $meta=DB::table('mobility_commute_demo_trips')->where('trip_id',$trip->id)->first();$hold=DB::table('mobility_commute_demo_holds')->where('booking_id',$b->id)->first();
  $terms=$meta->is_publication?app(CommuteMatchingService::class)->terms($b):$meta;
  if(!$terms)throw new SegmentException('COMMUTE_QUOTE_CHANGED',409);
  $journey=json_decode($terms->journey,true);
  $departure=$meta->is_publication?$terms->pickup_at:$trip->trip_date;
  return array_replace(['route_map'=>CommuteMatchingService::mapData($journey),'driver_route_origin_label'=>$journey['driver_origin']['label']??null,'driver_route_destination_label'=>$journey['driver_destination']['label']??null,'ride_meters'=>$journey['riding']['distance_meters']??0,'ride_seconds'=>$journey['riding']['duration_seconds']??0,'detour_meters'=>$journey['detour']['added_distance_meters']??0,'detour_seconds'=>$journey['detour']['added_duration_seconds']??0,'access_meters'=>$journey['access']['total_meters']??0,'egress_meters'=>$journey['egress']['total_meters']??0,'choice'=>$journey['choice']??'DIRECT_RIDER_PICKUP','pickup_label'=>$journey['rider_origin']['label']??'Scheduled pickup','dropoff_label'=>$journey['rider_destination']['label']??'Scheduled destination','vehicle_type'=>$meta->vehicle_type,'trip_id'=>$trip->id,'booking_id'=>$b->id,'rider_id'=>$b->user_id,'rider_name'=>User::whereKey($b->user_id)->value('name'),'driver_name'=>User::whereKey($trip->user_id)->value('name'),'owner'=>(int)$trip->user_id===$u->id,'request_state'=>(int)$b->request_state,'participant_state'=>DB::table('mobility_trip_participants')->where('trip_id',$trip->id)->where('user_id',$b->user_id)->value('state')??'accepted','state'=>DB::table('mobility_trip_lifecycles')->where('trip_id',$trip->id)->value('state'),'fare_minor'=>(int)$terms->fare_minor,'wallet_state'=>$hold->state??'unpaid','rider_arrived_at'=>$hold->arrived_at??null,'release_at'=>$hold->release_at??null,'can_drive'=>(int)$trip->user_id===$u->id,'departure_at'=>CarbonImmutable::parse($departure,'Asia/Kolkata')->toISOString(),'demo_fixture'=>true],CommuteMatchingService::presentation($journey,CarbonImmutable::parse($departure,'Asia/Kolkata')->toISOString()));
 }
 public function action(User$u,int$id,string$action):array{
  $this->requireDemo($u);return DB::transaction(function()use($u,$id,$action){$pre=Passenger::findOrFail($id);$trip=Trip::whereKey($pre->trip_id)->lock('for update nowait')->firstOrFail();$b=Passenger::whereKey($id)->lockForUpdate()->firstOrFail();$this->bookingDto($b,$u);$this->planned($trip);$owner=(int)$trip->user_id===$u->id;
   if($action!=='cancel'&&!$owner)throw new SegmentException('TRIP_OWNER_REQUIRED',403);
   $target=['accept'=>1,'reject'=>2,'cancel'=>3][$action];if((int)$b->request_state===$target)return['data'=>$this->bookingDto($b,$u)];
   if(($target!==3&&(int)$b->request_state!==0)||($target===3&&!in_array((int)$b->request_state,[0,1])))throw new SegmentException('BOOKING_STATE_CHANGED',409);
   if($target===1){$published=DB::table('mobility_commute_demo_trips')->where('trip_id',$trip->id)->value('is_publication');if($published)app(CommuteMatchingService::class)->accept($trip,$b);User::whereKey($u->id)->lock('for update nowait')->first();if(Passenger::where('trip_id',$trip->id)->where('request_state',1)->count()>=$trip->total_seats)throw new SegmentException('NOT_SEAT_AVAILABLE',422);
    // Demo driver still cannot accept simultaneous obligations on another trip.
    $conflict=Passenger::where('request_state',1)->where('trip_id','<>',$trip->id)->whereExists(function($q)use($trip,$u){$q->selectRaw('1')->from('trips as occupied')->join('mobility_trip_lifecycles as l','l.trip_id','=','occupied.id')->whereColumn('occupied.id','trip_passengers.trip_id')->where('occupied.user_id',$u->id)->whereIn('l.state',['planned','in_progress'])->whereBetween('occupied.trip_date',[CarbonImmutable::parse($trip->trip_date)->subHour(),CarbonImmutable::parse($trip->trip_date)->addHour()]);})->lockForUpdate()->first();if($conflict)throw new SegmentException('DRIVER_ROUTE_OVERLAP',409);
   }
   if($target===3)$this->refund($b);$b->request_state=$target;$b->save();return['data'=>$this->bookingDto($b,$u)];});
 }
 private function walletLock(int$id):object{DB::table('mobility_commute_demo_wallets')->insertOrIgnore(['user_id'=>$id,'available_minor'=>0,'created_at'=>now(),'updated_at'=>now()]);return DB::table('mobility_commute_demo_wallets')->where('user_id',$id)->lockForUpdate()->first();}
 private function entry(int$id,string$kind,int$amount,?int$booking=null):void{DB::table('mobility_commute_demo_entries')->insert(['user_id'=>$id,'kind'=>$kind,'amount_minor'=>$amount,'booking_id'=>$booking,'created_at'=>now(),'updated_at'=>now()]);}
 private function refund(Passenger$b):void{$hold=DB::table('mobility_commute_demo_holds')->where('booking_id',$b->id)->lockForUpdate()->first();if(!$hold||$hold->state!=='held')return;$w=$this->walletLock($b->user_id);DB::table('mobility_commute_demo_wallets')->where('user_id',$b->user_id)->increment('available_minor',$hold->amount_minor);DB::table('mobility_commute_demo_holds')->where('booking_id',$b->id)->update(['state'=>'refunded','updated_at'=>now()]);$this->entry($b->user_id,'refund',$hold->amount_minor,$b->id);}
 public function wallet(User$u):array{$this->requireDemo($u);$w=DB::table('mobility_commute_demo_wallets')->where('user_id',$u->id)->first();return['demo_only'=>true,'available_minor'=>(int)($w->available_minor??0),'held_minor'=>(int)DB::table('mobility_commute_demo_holds')->where('rider_id',$u->id)->where('state','held')->sum('amount_minor'),'pending_release_minor'=>(int)DB::table('mobility_commute_demo_holds')->where('driver_id',$u->id)->where('state','held')->sum('amount_minor'),'entries'=>DB::table('mobility_commute_demo_entries')->where('user_id',$u->id)->orderByDesc('id')->limit(30)->get()->all()];}
 public function topup(User$u,int$amount):array{$this->requireDemo($u);return DB::transaction(function()use($u,$amount){$w=$this->walletLock($u->id);if($w->available_minor+$amount>1000000)throw new SegmentException('DEMO_WALLET_LIMIT',422);DB::table('mobility_commute_demo_wallets')->where('user_id',$u->id)->increment('available_minor',$amount);$this->entry($u->id,'demo_credit',$amount);return$this->wallet($u);});}
 public function pay(User$u,int$id):array{$this->requireDemo($u);return DB::transaction(function()use($u,$id){$pre=Passenger::findOrFail($id);$trip=Trip::whereKey($pre->trip_id)->lock('for update nowait')->firstOrFail();$b=Passenger::whereKey($id)->lockForUpdate()->firstOrFail();if((int)$b->user_id!==$u->id)throw new SegmentException('RIDER_REQUIRED',403);$this->planned($trip);if((int)$b->request_state!==1)throw new SegmentException('ACCEPTED_BOOKING_REQUIRED',409);$meta=DB::table('mobility_commute_demo_trips')->where('trip_id',$trip->id)->first();if(!$meta)throw new SegmentException('DEMO_TRIP_REQUIRED',403);if($meta->is_publication){$meta=app(CommuteMatchingService::class)->terms($b);if(!$meta)throw new SegmentException('COMMUTE_QUOTE_CHANGED',409);}$hold=DB::table('mobility_commute_demo_holds')->where('booking_id',$id)->first();if($hold)return['data'=>$this->bookingDto($b,$u)];$wallet=$this->walletLock($u->id);if($wallet->available_minor<$meta->fare_minor)throw new SegmentException('INSUFFICIENT_DEMO_CREDITS',422);DB::table('mobility_commute_demo_wallets')->where('user_id',$u->id)->decrement('available_minor',$meta->fare_minor);DB::table('mobility_commute_demo_holds')->insert(['booking_id'=>$id,'rider_id'=>$u->id,'driver_id'=>$trip->user_id,'amount_minor'=>$meta->fare_minor,'state'=>'held','created_at'=>now(),'updated_at'=>now()]);$this->entry($u->id,'ride_hold',-$meta->fare_minor,$id);return['data'=>$this->bookingDto($b,$u)];});}
 public function arrive(User$u,int$id):array{$this->requireDemo($u);return DB::transaction(function()use($u,$id){$pre=Passenger::findOrFail($id);Trip::whereKey($pre->trip_id)->lock('for update nowait')->firstOrFail();$b=Passenger::whereKey($id)->lockForUpdate()->firstOrFail();if((int)$b->user_id!==$u->id)throw new SegmentException('RIDER_REQUIRED',403);$hold=DB::table('mobility_commute_demo_holds')->where('booking_id',$id)->lockForUpdate()->first();if(!$hold||$hold->state!=='held'||DB::table('mobility_trip_lifecycles')->where('trip_id',$b->trip_id)->value('state')!=='completed')throw new SegmentException('COMPLETE_PAID_TRIP_REQUIRED',409);if(!$hold->arrived_at)DB::table('mobility_commute_demo_holds')->where('booking_id',$id)->update(['arrived_at'=>now('UTC'),'release_at'=>now('UTC')->addHours(3),'updated_at'=>now()]);return['data'=>$this->bookingDto($b,$u)];});}
 public function release(User$u):array{$this->requireDemo($u);$ids=DB::table('mobility_commute_demo_holds')->where('driver_id',$u->id)->where('state','held')->whereNotNull('arrived_at')->where('release_at','<=',now('UTC'))->pluck('booking_id');foreach($ids as$id)DB::transaction(function()use($u,$id){$pre=Passenger::findOrFail($id);Trip::whereKey($pre->trip_id)->lock('for update nowait')->firstOrFail();$h=DB::table('mobility_commute_demo_holds')->where('booking_id',$id)->lockForUpdate()->first();if($h->state!=='held'||!$h->arrived_at||CarbonImmutable::parse($h->release_at,'UTC')->gt(now('UTC'))||DB::table('mobility_trip_lifecycles')->where('trip_id',$pre->trip_id)->value('state')!=='completed')return;$this->walletLock($u->id);DB::table('mobility_commute_demo_wallets')->where('user_id',$u->id)->increment('available_minor',$h->amount_minor);DB::table('mobility_commute_demo_holds')->where('booking_id',$id)->update(['state'=>'released','updated_at'=>now()]);$this->entry($u->id,'driver_release',$h->amount_minor,$id);});return$this->wallet($u);}
 public function receipt(User$u,string$key,array$body,\Closure$action):array{if(!preg_match('/^[\x21-\x7E]{1,100}$/',$key))throw new SegmentException('INVALID_IDEMPOTENCY_KEY',422);$hash=hash('sha256',json_encode($body));try{return DB::transaction(function()use($u,$key,$hash,$action){User::whereKey($u->id)->lock('for update nowait')->first();$old=DB::table('mobility_commute_receipts')->where('user_id',$u->id)->where('key_hash',hash('sha256',$key))->first();if($old){if(!hash_equals($old->request_hash,$hash))throw new SegmentException('IDEMPOTENCY_CONFLICT',409);return json_decode($old->response,true);}$response=$action();DB::table('mobility_commute_receipts')->insert(['user_id'=>$u->id,'key_hash'=>hash('sha256',$key),'request_hash'=>$hash,'response'=>json_encode($response),'created_at'=>now(),'updated_at'=>now()]);return$response;});}catch(QueryException$e){if(in_array((int)($e->errorInfo[1]??0),[1205,1213,3572],true))throw new SegmentException('COMMUTE_BUSY_RETRY',409);throw$e;}}
}
